import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:ital,wght@0,400;0,600;0,700;1,400;1,600;1,700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type LuxuryQuestionProps = Record<string, any>;

const LuxuryQuestion: React.FC<LuxuryQuestionProps> = ({
  backgroundColor = "#8B0000",
  transparentBackground = false,
  durationInSeconds = 3,
  questionText = "How Does Someone Book Jad?",
  primaryColor = "#D4AF37",
  textColor = "#F5F5DC",
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Cormorant Garamond"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height);

  // Parse background to allow transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Icon Animations
  const iconOpacity = interpolate(frame, [0, 25], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const glowRadius = interpolate(frame, [15, 50], [0, 40], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // Text Animation (Spring Slide Up)
  const textRevealProgress = spring({
    frame: frame - 20,
    fps,
    config: { damping: 18, stiffness: 70, mass: 1.2 }, // Elegant, smooth settling
  });

  const textTranslateY = interpolate(textRevealProgress, [0, 1], [120, 0]);
  const textOpacity = interpolate(textRevealProgress, [0, 0.5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Underline Animation (Sweep Left to Right)
  const lineProgress = spring({
    frame: frame - 35,
    fps,
    config: { damping: 20, stiffness: 60, mass: 1 },
  });

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Cormorant Garamond, serif",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div 
        style={{ 
          display: "flex", 
          flexDirection: "column", 
          alignItems: "center", 
          width: width * 0.85,
          transition: "none",
        }}
      >
        {/* Elegant Question Mark Icon */}
        <div 
          style={{
            fontSize: s * 0.35,
            fontWeight: 400,
            fontStyle: "italic",
            color: primaryColor,
            opacity: iconOpacity,
            textShadow: `0px 0px ${glowRadius}px ${primaryColor}66`, // Add 40% hex opacity to shadow
            marginBottom: s * 0.05,
            lineHeight: 0.8,
            transition: "none",
          }}
        >
          ?
        </div>

        {/* Text Reveal Container */}
        <div 
          style={{ 
            overflow: "hidden", 
            paddingBottom: s * 0.02,
            width: "100%",
            display: "flex",
            justifyContent: "center",
            transition: "none",
          }}
        >
          <div 
            style={{
              transform: `translateY(${textTranslateY}%)`,
              opacity: textOpacity,
              fontSize: s * 0.09,
              fontWeight: 700,
              color: textColor,
              textAlign: "center",
              lineHeight: 1.2,
              transition: "none",
            }}
          >
            {questionText}
          </div>
        </div>

        {/* Sweeping Gold Underline */}
        <div 
          style={{
            marginTop: s * 0.02,
            height: Math.max(3, s * 0.004),
            width: "100%",
            maxWidth: width * 0.65,
            backgroundColor: primaryColor,
            transformOrigin: "left center",
            transform: `scaleX(${lineProgress})`,
            boxShadow: `0px 2px 10px ${primaryColor}33`,
            transition: "none",
            borderRadius: 2,
          }} 
        />
      </div>
    </AbsoluteFill>
  );
};

export default LuxuryQuestion;